const body = $('Webhook').first().json.body;
const upstream = $('HTTP Request').first().json;
const context = upstream.body;
if (upstream.statusCode !== 200 || typeof context?.use_model !== 'boolean' || context.suppress === true) {
  return [{ json: { skip_api: true } }];
}
const payload = { session_id: body?.session_id, message_id: body?.message_id, mensagem: body?.mensagem };
if (context.use_model) {
  const input = $input.first().json;
  const parts = input?.content?.parts ?? input?.candidates?.[0]?.content?.parts;
  const raw = Array.isArray(parts) ? parts.filter(p => !p.thought && typeof p.text === 'string').map(p => p.text).join('') : '';
  const noFields = ['greeting', 'menu', 'pickup', 'payments', 'pix', 'summary', 'human', 'clarify'];
  const limits = { price: 80, availability: 80, remove: 80, add: 80, change: 80, delivery: 100,
    shipping: 100, payment: 100, name: 100, address: 180 };
  function validate(action) {
    const type = action?.type;
    if (noFields.includes(type)) return { type };
    const value = typeof action?.value === 'string' ? action.value.trim() : '';
    if (type === 'delivery' && !value) return { type };
    if (type === 'faq') return Object.hasOwn(context.knowledge?.faq ?? {}, value) ? { type, value } : null;
    if (type === 'phone') {
      if (!/^[\d\s()+.-]+$/.test(value)) return null;
      const digits = value.replace(/\D/g, '');
      return /^\d{10,11}$/.test(digits) ? { type, value: digits } : null;
    }
    if (!Object.hasOwn(limits, type) || !value || value.length > limits[type] || /\p{Cc}/u.test(value)) return null;
    if (type === 'add' || type === 'change') {
      const quantity = typeof action.quantity === 'string' && /^\d+$/.test(action.quantity)
        ? Number(action.quantity) : action.quantity;
      return Number.isInteger(quantity) && quantity >= 1 && quantity <= 100 ? { type, value, quantity } : null;
    }
    return { type, value };
  }
  try {
    const clean = raw.trim().replace(/^```(?:json)?\s*|\s*```$/gi, '');
    const result = JSON.parse(clean);
    if (Array.isArray(result?.actions) && result.actions.length <= 12) {
      const actions = result.actions.map(validate).filter(Boolean);
      if (actions.length) payload.interpretacao = { actions };
    }
  } catch {
    // A API orienta o cliente quando o modelo falha.
  }
}
return [{ json: payload }];

const context = $('HTTP Request').first().json;
const output = $input.first().json;
function response(statusCode, body) { return [{ json: { statusCode, body } }]; }
function failure(stage, upstream) {
  const known = [400, 401, 403, 404, 409, 413, 429, 503];
  const status = known.includes(upstream?.statusCode) ? upstream.statusCode : 502;
  const messages = {
    400: "Dados do webhook inválidos. Confira session_id, message_id e mensagem.",
    401: "A API recusou a credencial. Configure Header Auth com x-integration-token e o WEBHOOK_TOKEN da API.",
    403: "A API não autorizou esta requisição.",
    404: "Rota da integração não encontrada. Confira a URL do node.",
    409: "A API recusou a operação por conflito.",
    413: "A requisição excedeu o limite da API.",
    429: "A API atingiu o limite de requisições.",
    502: "A API não retornou uma resposta válida. Confira a conexão e o estado do serviço.",
    503: "A integração está indisponível. Confira WEBHOOK_TOKEN e o modo da API."
  };
  return response(status, { error: messages[status], etapa: stage });
}
if (context.statusCode !== 200 || typeof context.body?.use_model !== "boolean") return failure("contexto", context);
if (context.body.suppress === true) return response(200, { resposta: "", suprimir_resposta: true });
if (output.statusCode !== 200) return failure("conversa", output);
const body = output.body;
if (body?.suprimir_resposta === true && body.resposta === "") return response(200, { resposta: "", suprimir_resposta: true });
if (typeof body?.resposta !== "string" || !body.resposta.trim()) return failure("conversa", null);
return response(200, { resposta: body.resposta });
